MATCH (d:Division {name: "Chattogram"})<-[:IN_DIVISION]-(dist:District)
MATCH (c:Crop {name: "Lentil"})-[produces:PRODUCED_IN {crop_year: "2018-19"}]->(dist)
RETURN SUM(produces.production_mt) AS answer;

MATCH (c:Crop {name: "Aman"})-[p:PRODUCED_IN]->(d:District {name: "Naogaon"}) 
WHERE p.crop_year IN ["2019-20", "2023-24"] 
RETURN p.crop_year AS year, p.production_mt AS answer;
